SELECT skill_tag_nm FROM TBL_SALARY_SUBMISSION_SKILL_S
WHERE salary_submission_sq = #{salarySubmissionSq}
ORDER BY salary_submission_skill_sq

mapper.sql:
WHERE m.job_nm = #{jobNm}
AND m.career_bucket = #{careerBucket}
AND m.region_nm = #{regionNm}
AND m.employment_type = #{employmentType}
AND m.is_seed_yn = 'N'

mapper.select:
SELECT COUNT(*) FROM TBL_SALARY_SUBMISSION_M m
WHERE m.job_nm = #{jobNm}
AND m.career_bucket = #{careerBucket}
AND m.region_nm = #{regionNm}
AND m.employment_type = #{employmentType}
AND m.is_seed_yn = 'N'

SELECT skl.skill_tag_nm AS skill, AVG(m.annual_salary) AS avgSalary, COUNT(*) AS sampleCount
FROM TBL_SALARY_SUBMISSION_SKILL_S skl
JOIN TBL_SALARY_SUBMISSION_M m ON m.salary_submission_sq = skl.salary_submission_sq
WHERE m.job_nm = #{jobNm}
AND m.career_bucket = #{careerBucket}
AND m.region_nm = #{regionNm}
AND m.employment_type = #{employmentType}

    AND skl.skill_tag_nm NOT IN
    #{s}

GROUP BY skl.skill_tag_nm
HAVING COUNT(*) >= 5

SELECT TRIM(m.company_nm) AS companyNm, COUNT(*) AS matchedCount, ROUND(AVG(m.annual_salary)) AS avgSalary
FROM TBL_SALARY_SUBMISSION_M m
WHERE m.job_nm = #{jobNm}
AND m.career_bucket = #{careerBucket}
AND m.region_nm = #{regionNm}
AND m.employment_type = #{employmentType}
AND m.is_seed_yn = 'N'
AND m.company_nm IS NOT NULL AND TRIM(m.company_nm) != ''
GROUP BY TRIM(m.company_nm)
HAVING COUNT(*) >= 3
ORDER BY matchedCount DESC
LIMIT 5

